import React, { useEffect, useState } from 'react';
import { Table, Button, Spinner } from 'react-bootstrap';

function ProductsList() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showEditModal, setShowEditModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);

  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newProduct, setNewProduct] = useState({ nom: '', referencia: '', descripcio: '', quantitat: 0 });

  const token = localStorage.getItem('token');

  // =========================
  // FETCH PRODUCTS
  // =========================
  const fetchProducts = async () => {
    try {
      const res = await fetch('http://localhost/api/productes', {
        headers: {
          Accept: 'application/json',
          Authorization: token ? `Bearer ${token}` : undefined
        }
      });
      if (!res.ok) throw new Error('Error al obtenir els productes');
      const data = await res.json();
      setProducts(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);

  // =========================
  // DELETE PRODUCT
  // =========================
  const handleDelete = async (id) => {
    if (!token) { alert('No estás autenticado.'); return; }
    if (!window.confirm('Segur que vols eliminar aquest producte?')) return;

    try {
      const res = await fetch(`http://localhost/api/productes/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
      });
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error eliminant producte');
      setProducts(products.filter(p => p.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  // =========================
  // EDIT PRODUCT
  // =========================
  const openEditModal = (product) => {
    setEditingProduct({ ...product });
    setShowEditModal(true);
  };

  const handleEditChange = (e) => {
    setEditingProduct({ ...editingProduct, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    if (!token) { alert('No estás autenticado.'); return; }
    try {
      const res = await fetch(`http://localhost/api/productes/${editingProduct.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify(editingProduct)
      });
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error actualitzant producte');
      setProducts(products.map(p => p.id === editingProduct.id ? editingProduct : p));
      setShowEditModal(false);
    } catch (err) { alert(err.message); }
  };

  // =========================
  // CREATE PRODUCT
  // =========================
  const handleNewChange = (e) => {
    setNewProduct({ ...newProduct, [e.target.name]: e.target.value });
  };

  const handleCreate = async () => {
    if (!token) { alert('No estás autenticado.'); return; }
    try {
      const res = await fetch('http://localhost/api/productes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify(newProduct)
      });
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error creant producte');
      setProducts([...products, data.producte]); // asumimos que el backend devuelve el nuevo producto
      setNewProduct({ nom: '', referencia: '', descripcio: '', quantitat: 0 });
      setShowCreateModal(false);
    } catch (err) { alert(err.message); }
  };

  // =========================
  // RENDER
  // =========================
  if (loading) return <div className="text-center mt-5"><Spinner animation="border" /></div>;
  if (error) return <p>Error: {error}</p>;

  return (
    <div className="mt-4">
      <h2>Llista de Productes</h2>
      <Button variant="primary" onClick={() => setShowCreateModal(true)}>Crear Producte</Button>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nom</th>
            <th>Referència</th>
            <th>Descripció</th>
            <th>Quantitat</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {products.map(product => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.nom}</td>
              <td>{product.referencia}</td>
              <td>{product.descripcio}</td>
              <td>{product.quantitat}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2" onClick={() => openEditModal(product)}>Editar</Button>
                <Button variant="danger" size="sm" onClick={() => handleDelete(product.id)}>Eliminar</Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {/* ========================= EDIT MODAL ========================= */}
      {showEditModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Editar producte</h5>
                <button type="button" className="btn-close" onClick={() => setShowEditModal(false)} />
              </div>
              <div className="modal-body">
                <input className="form-control mb-2" name="nom" value={editingProduct.nom} onChange={handleEditChange} placeholder="Nom" />
                <input className="form-control mb-2" name="referencia" value={editingProduct.referencia} onChange={handleEditChange} placeholder="Referència" />
                <textarea className="form-control mb-2" name="descripcio" value={editingProduct.descripcio} onChange={handleEditChange} placeholder="Descripció" />
                <input type="number" className="form-control" name="quantitat" value={editingProduct.quantitat} onChange={handleEditChange} placeholder="Quantitat" />
              </div>
              <div className="modal-footer">
                <Button variant="secondary" onClick={() => setShowEditModal(false)}>Cancel·lar</Button>
                <Button variant="success" onClick={handleSave}>Guardar</Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* ========================= CREATE MODAL ========================= */}
      {showCreateModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Crear producte</h5>
                <button type="button" className="btn-close" onClick={() => setShowCreateModal(false)} />
              </div>
              <div className="modal-body">
                <input className="form-control mb-2" name="nom" value={newProduct.nom} onChange={handleNewChange} placeholder="Nom" />
                <input className="form-control mb-2" name="referencia" value={newProduct.referencia} onChange={handleNewChange} placeholder="Referència" />
                <textarea className="form-control mb-2" name="descripcio" value={newProduct.descripcio} onChange={handleNewChange} placeholder="Descripció" />
                <input type="number" className="form-control" name="quantitat" value={newProduct.quantitat} onChange={handleNewChange} placeholder="Quantitat" />
              </div>
              <div className="modal-footer">
                <Button variant="secondary" onClick={() => setShowCreateModal(false)}>Cancel·lar</Button>
                <Button variant="success" onClick={handleCreate}>Crear</Button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

export default ProductsList;
